  singularity:{
    id:'singularity', name:'Singularity', icon:'⭕',
    cost:40, costType:'mp', cooldown:0, maxCooldown:3, color:'#7744bb', element:'shadow',
    desc:'Compress reality. 250% ATK. Doubles current Entropy stacks on target.',
    tags:['magic','void'],
    use:(p,e)=>{
      const dmg=calcDmg(p.stats.atk*2.5,e.def*0.3);
      dealDmgToEnemy(e,dmg,false,false,true,'shadow');
      const b=e.status&&e.status.find(s=>s.id==='entropy');
      if(b){
        const extraStacks=Math.min(10,b.stacks*2)-b.stacks;
        const extraPen=extraStacks*2;
        e.atk=Math.max(1,e.atk-extraPen); e.def=Math.max(0,e.def-extraPen);
        b.atkPen=(b.atkPen||0)+extraPen; b.defPen=(b.defPen||0)+extraPen;
        b.stacks=Math.min(10,b.stacks*2);
      }
      return `Singularity implodes for ${dmg}! Entropy doubled to x${getEntropyStacks(e)}.`;
    }
  },
