  // ── PALADIN: Radiant Aura ─────────────────────────────────
  radiant_aura:{
    id:'radiant_aura', name:'Radiant Aura', icon:'🌟',
    cost:25, costType:'mp', cooldown:0, maxCooldown:3, color:'#eecc44', element:'fairy',
    desc:'Surround yourself with divine light. Heal 20% max HP. Cleanse all debuffs. +10 DEF for 2 turns.',
    tags:['buff','holy','heal'],
    use:(p,e)=>{
      // Cleanse debuffs (restore any stat penalties first)
      p.status.forEach(s=>{
        if (s.type==='debuff') {
          if (s.defPen) p.stats.def = Math.min(999, p.stats.def + s.defPen);
          if (s.atkPen) p.stats.atk = Math.min(999, p.stats.atk + s.atkPen);
        }
      });
      p.status = p.status.filter(s=>s.type!=='debuff');
      const heal = Math.round(p.stats.maxHp * 0.20);
      p.stats.hp = Math.min(p.stats.maxHp, p.stats.hp + heal);
      addStatus(p,{id:'radiant_aura',name:'Radiant',type:'buff',icon:'🌟',duration:2,defBonus:10});
      p.stats.def += 10;
      logEntry('heal',`Radiant Aura heals ${heal} HP and cleanses debuffs!`);
      return `Radiant Aura blazes! Healed ${heal}, all debuffs cleansed, +10 DEF.`;
    }
  },

