  holy_nova:{
    id:'holy_nova', name:'Holy Nova', icon:'💫',
    cost:35, costType:'mp', cooldown:0, maxCooldown:3, color:'#ffffcc', element:'fairy',
    desc:'Holy burst. 180% ATK holy. Heal 20% max HP. Cleanse 1 debuff.',
    tags:['magic','holy','heal'],
    use:(p,e)=>{
      const dmg = calcDmg(p.stats.atk*1.8, e.def*0.5);
      dealDmgToEnemy(e, dmg, false, false, true, 'fairy');
      const heal = Math.round(p.stats.maxHp*0.20);
      p.stats.hp = Math.min(p.stats.maxHp, p.stats.hp+heal);
      const debuffIdx = p.status.findIndex(s=>s.type==='debuff');
      if(debuffIdx>=0){ const s=p.status[debuffIdx]; if(s.defPen)p.stats.def+=s.defPen; if(s.atkPen)p.stats.atk+=s.atkPen; p.status.splice(debuffIdx,1); }
      logEntry('heal',`Holy Nova heals ${heal} HP!`);
      return `Holy Nova blazes for ${dmg}! Healed ${heal}. Debuff cleansed.`;
    }
  },
