      dealDmgToEnemy(e,dmg,isCrit,false,true,null);
      if(form==='drain'){ const heal=dmg; p.stats.hp=Math.min(p.stats.maxHp,p.stats.hp+heal); return `Overload hits ${dmg}, heals ${heal} in Drain Form.`; }
      if(form==='control'){ addStatus(e,{id:'stun',name:'Overloaded',type:'debuff',icon:'⚡',duration:3,onTurn:(en)=>{logEntry('system',`${en.name} is overloaded — cannot act!`);}}); return `Overload stuns 3 turns for ${dmg} in Control Form!`; }
