        let det=0; e.status.filter(s=>s.disease).forEach(()=>{ const d=Math.round(calcDmg(p.stats.atk*2.0,e.def*0.1)); dealDmgToEnemy(e,d,true,false,true,null); det+=d; });
        e.status=e.status.filter(s=>!s.disease);
        return `Overload applies + detonates all diseases for ${dmg+det} total in DoT Form!`;
