ABILITIES.shadow_normal_strike = {
  id:'shadow_normal_strike', name:'Cruel Edge', icon:'🗡️',
  cost:14, costType:'mp', cooldown:0, maxCooldown:0, color:'#888888', element:'normal',
  desc:'A ruthlessly efficient strike. 170% ATK physical. +20% crit chance.',
  tags:['physical','crit'],
  use:(p,e)=>{
    const critChance=Math.min(95,p.stats.crit+20);
    const isCrit=rand(100)<critChance; const critMult=1.8+((p.stats.critDmg||0)/100);
    const dmg=Math.round(calcDmg(p.stats.atk*1.7,e.def)*(isCrit?critMult:1));
    dealDmgToEnemy(e,dmg,isCrit,false,false,'normal');
    return isCrit?`Cruel Edge CRITS for ${dmg}!`:`Cruel Edge cuts for ${dmg}.`;
  }
};
