// ── GENERATED ABILITY DEFINITIONS ────────────────────────────

// ══════════════════════════════════════════════════════════════
// The bulk of ABILITIES (the generated hybrid / element-combo abilities,
// ~8 MB) lives in abilities_generated.js and loads in the background after
// the title screen appears. Anything that needs every ability (starting or
// continuing a run, tests) awaits ensureAbilitiesLoaded() first.
// ══════════════════════════════════════════════════════════════
let _abilitiesLoad = null;
function ensureAbilitiesLoaded() {
  if (window.ABILITIES_GENERATED_LOADED) return Promise.resolve();
  if (!_abilitiesLoad) {
    _abilitiesLoad = new Promise((resolve, reject) => {
      const script = document.createElement('script');
      script.src = 'js/data/abilities_generated.js';
      script.onload = () => { window.ABILITIES_GENERATED_LOADED = true; resolve(); };
      script.onerror = () => { _abilitiesLoad = null; script.remove(); reject(new Error('Failed to load abilities_generated.js')); };
      document.head.appendChild(script);
    });
  }
  return _abilitiesLoad;
}
